#[test]
fn experiment_oversized_not_listed() {
    let root = project();
    let sources = AssessmentSources::prepare(root.path(), "requirements.ready").unwrap();
    let extras = json!((0..1000).map(|i| format!("src/{i}_{}.rs", "x".repeat(70))).collect::<Vec<_>>());
    let listing = Listing::array(vec![json!({"path":"src/tracked.rs","kind":"file"})])
        .with_extra("not_listed", extras.clone());
    let page = ResultPages::default().deliver(&sources, listing).unwrap();
    println!("first page bytes: {}, limit: {}", page.result.to_string().len(), PAGE_LIMIT);
    assert!(page.result.to_string().len() > PAGE_LIMIT);
    let empty = Listing::array(vec![]).with_extra("not_listed", extras);
    let panic = std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| {
        ResultPages::default().deliver(&sources, empty)
    }));
    assert!(panic.is_err(), "expected the reported empty-listing panic");
}
